-- =============================================================================
-- 02_bronze_load.sql  |  Bronze: one table per source object + COPY INTO
-- Column names/types mirror the CSV extracts in data/bronze exactly.
-- Every table carries the four audit columns: src_system, extracted_at, batch_id, row_hash.
-- Upload first (SnowSQL / Snowsight "+ Files"):
--   PUT file://<pack>/data/bronze/*.csv    @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/    AUTO_COMPRESS=FALSE;
--   PUT file://<pack>/data/bad_files/*.csv @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bad_files/ AUTO_COMPRESS=FALSE;
-- =============================================================================
USE ROLE ROLE_ELT_ADMIN;
USE WAREHOUSE WH_ELT;
USE SCHEMA EDW_BRONZE.RAW;

-- ------------------------------------------------------------------ SAP S/4HANA
CREATE OR REPLACE TABLE SAP_GL_ACTUALS_MONTHLY (
  BUKRS VARCHAR(4), GJAHR VARCHAR(4), MONAT NUMBER(2), KOSTL VARCHAR(10), HKONT VARCHAR(10), PRCTR VARCHAR(10),
  WAERS VARCHAR(3), WRBTR NUMBER(18,2), HWAER VARCHAR(3), DMBTR NUMBER(18,2), POSTING_COUNT NUMBER(9), BUDAT DATE,
  src_system VARCHAR(20), extracted_at TIMESTAMP_NTZ, batch_id VARCHAR(50), row_hash VARCHAR(32)
) COMMENT = 'SAP CO/FI monthly actuals at company code x cost centre x GL x profit centre grain';

CREATE OR REPLACE TABLE SAP_CO_BUDGET_MONTHLY (
  BUKRS VARCHAR(4), GJAHR VARCHAR(4), MONAT NUMBER(2), KOSTL VARCHAR(10), HKONT VARCHAR(10), PRCTR VARCHAR(10),
  VERSN VARCHAR(3), PLAN_AMOUNT_USD NUMBER(18,2),
  src_system VARCHAR(20), extracted_at TIMESTAMP_NTZ, batch_id VARCHAR(50), row_hash VARCHAR(32)
) COMMENT = 'SAP CO plan version 0 (annual budget phased monthly)';

CREATE OR REPLACE TABLE SAP_PURCHASE_ORDERS (
  EBELN VARCHAR(10), EBELP VARCHAR(5), BEDAT DATE, LIFNR VARCHAR(10), NAME1 VARCHAR(120), BUKRS VARCHAR(4), KOSTL VARCHAR(10),
  SAKTO VARCHAR(10), MATKL VARCHAR(60), TXZ01 VARCHAR(200), MENGE NUMBER(12), NETWR NUMBER(18,2), WAERS VARCHAR(3),
  ARIBA_REQ_ID VARCHAR(20), STATUS VARCHAR(20),
  src_system VARCHAR(20), extracted_at TIMESTAMP_NTZ, batch_id VARCHAR(50), row_hash VARCHAR(32)
) COMMENT = 'SAP MM purchase order lines (EKKO/EKPO)';

CREATE OR REPLACE TABLE SAP_VENDOR_MASTER (
  LIFNR VARCHAR(10), NAME1 VARCHAR(120), LAND1 VARCHAR(3), STCD1 VARCHAR(20), IBAN VARCHAR(34), ZTERM VARCHAR(10), KTOKK VARCHAR(4),
  CATEGORY VARCHAR(60), ERNAM VARCHAR(30), ERDAT DATE, LOEVM VARCHAR(1),
  src_system VARCHAR(20), extracted_at TIMESTAMP_NTZ, batch_id VARCHAR(50), row_hash VARCHAR(32)
) COMMENT = 'SAP vendor master (LFA1/LFB1) - contains 17 duplicate records created by Ariba sync';

-- ------------------------------------------------------------------ SAP SuccessFactors
CREATE OR REPLACE TABLE SF_EMPLOYEE_MASTER (
  PERSON_ID_EXTERNAL VARCHAR(10), FIRST_NAME VARCHAR(60), LAST_NAME VARCHAR(60), GENDER VARCHAR(1), NATIONALITY VARCHAR(2),
  NATIONAL_ID VARCHAR(20), DATE_OF_BIRTH DATE, LEGAL_ENTITY VARCHAR(80), COST_CENTER VARCHAR(10), DEPARTMENT VARCHAR(80),
  JOB_TITLE VARCHAR(80), PAY_GRADE VARCHAR(3), EMPLOYMENT_TYPE VARCHAR(20), SHIFT_PATTERN VARCHAR(10), HIRE_DATE DATE,
  TERMINATION_DATE DATE, EMP_STATUS VARCHAR(1), BASE_SALARY NUMBER(12,2), HOUSING_ALLOWANCE NUMBER(12,2), PAY_CURRENCY VARCHAR(3),
  MANAGER_ID VARCHAR(10), EMAIL VARCHAR(120),
  src_system VARCHAR(20), extracted_at TIMESTAMP_NTZ, batch_id VARCHAR(50), row_hash VARCHAR(32)
) COMMENT = 'SuccessFactors Employee Central snapshot (permanent staff). Contains PII and payroll.';

CREATE OR REPLACE TABLE SF_TIME_ENTRIES_MONTHLY (
  PERSON_ID_EXTERNAL VARCHAR(10), PERIOD VARCHAR(7), TIME_TYPE_REGULAR_HRS NUMBER(7,2), TIME_TYPE_OT_HRS NUMBER(7,2),
  TIME_TYPE_NIGHT_HRS NUMBER(7,2), TIME_TYPE_LEAVE_HRS NUMBER(7,2), OT_MULTIPLIER NUMBER(4,2), APPROVAL_STATUS VARCHAR(10),
  src_system VARCHAR(20), extracted_at TIMESTAMP_NTZ, batch_id VARCHAR(50), row_hash VARCHAR(32)
) COMMENT = 'SuccessFactors Time: approved monthly hours per employee (2026 extracts; 2025 history via archive load)';

-- ------------------------------------------------------------------ SAP Ariba
CREATE OR REPLACE TABLE ARIBA_SUPPLIERS (
  SUPPLIER_ID VARCHAR(12), ERP_VENDOR_ID VARCHAR(10), SUPPLIER_NAME VARCHAR(120), COMMODITY VARCHAR(60), TAX_ID VARCHAR(20),
  BANK_ACCOUNT VARCHAR(34), COUNTRY VARCHAR(3), REGISTRATION_STATUS VARCHAR(20), RISK_SCORE NUMBER(2),
  src_system VARCHAR(20), extracted_at TIMESTAMP_NTZ, batch_id VARCHAR(50), row_hash VARCHAR(32)
);

CREATE OR REPLACE TABLE ARIBA_REQUISITIONS (
  REQUISITION_ID VARCHAR(12), REQ_DATE DATE, REQUESTER VARCHAR(10), SUPPLIER_ID VARCHAR(12), COMMODITY VARCHAR(60), COST_CENTER VARCHAR(10),
  AMOUNT NUMBER(18,2), CURRENCY VARCHAR(3), APPROVAL_STATUS VARCHAR(20), ERP_PO_NUMBER VARCHAR(10), CONTRACT_ID VARCHAR(12), CYCLE_TIME_DAYS NUMBER(4),
  src_system VARCHAR(20), extracted_at TIMESTAMP_NTZ, batch_id VARCHAR(50), row_hash VARCHAR(32)
);

-- ------------------------------------------------------------------ IBM Maximo
CREATE OR REPLACE TABLE MAXIMO_ASSETS (
  ASSETNUM VARCHAR(12), DESCRIPTION VARCHAR(120), ASSETTYPE VARCHAR(5), MANUFACTURER VARCHAR(40), MODEL VARCHAR(40), INSTALLDATE DATE,
  PURCHASEPRICE NUMBER(14,2), SITEID VARCHAR(10), LOCATION VARCHAR(20), GLACCOUNT VARCHAR(12), STATUS VARCHAR(40), PRIORITY NUMBER(1), CHANGEDATE DATE,
  src_system VARCHAR(20), extracted_at TIMESTAMP_NTZ, batch_id VARCHAR(50), row_hash VARCHAR(32)
);

CREATE OR REPLACE TABLE MAXIMO_WORK_ORDERS (
  WONUM VARCHAR(12), ASSETNUM VARCHAR(12), SITEID VARCHAR(10), WORKTYPE VARCHAR(4), FAILURECODE VARCHAR(8), PROBLEMCODE VARCHAR(80), WOPRIORITY NUMBER(1),
  REPORTDATE TIMESTAMP_NTZ, ACTSTART TIMESTAMP_NTZ, ACTFINISH TIMESTAMP_NTZ, DOWNTIME_HRS NUMBER(8,2), ACTLABHRS NUMBER(8,2), ACTMATCOST NUMBER(12,2),
  ACTLABCOST NUMBER(12,2), STATUS VARCHAR(8), LEAD VARCHAR(10), GLACCOUNT VARCHAR(12),
  src_system VARCHAR(20), extracted_at TIMESTAMP_NTZ, batch_id VARCHAR(50), row_hash VARCHAR(32)
);

CREATE OR REPLACE TABLE MAXIMO_METER_READINGS (
  ASSETNUM VARCHAR(12), METERNAME VARCHAR(20), PERIOD VARCHAR(7), READING_HRS NUMBER(9,1), READING_DATE DATE,
  src_system VARCHAR(20), extracted_at TIMESTAMP_NTZ, batch_id VARCHAR(50), row_hash VARCHAR(32)
);

-- ------------------------------------------------------------------ Catering Management System (CMS)
CREATE OR REPLACE TABLE CMS_UPLIFT_FLIGHT_CLASS (
  UPLIFT_ID VARCHAR(20), FLT_DATE DATE, CARRIER VARCHAR(5), FLT_NO VARCHAR(10), DEP_STN VARCHAR(4), DEST VARCHAR(5), AC_TYPE VARCHAR(6), CLASS VARCHAR(1),
  MENU_SPEC VARCHAR(12), MEALS_PLANNED NUMBER(7), MEALS_UPLIFTED NUMBER(7), MEALS_DOWNLIFTED NUMBER(7), MEALS_WASTED NUMBER(7),
  DOWNLIFT_LATE_FLAG VARCHAR(1), DELIVERY_ON_TIME_FLAG VARCHAR(1), FOOD_COST NUMBER(12,2), LABOUR_COST NUMBER(12,2), OVERHEAD_COST NUMBER(12,2),
  BILL_AMOUNT NUMBER(12,2), CURRENCY VARCHAR(3), KITCHEN VARCHAR(10),
  src_system VARCHAR(20), extracted_at TIMESTAMP_NTZ, batch_id VARCHAR(50), row_hash VARCHAR(32)
) COMMENT = 'CMS live feed - flight x class uplift records (Sep-2026 batch). Contains raw-data defects on purpose: 26 exact duplicates, lower-case carrier codes, padded destinations.';

CREATE OR REPLACE TABLE CMS_UPLIFT_DAILY_HISTORY (
  UPLIFT_DATE DATE, CARRIER VARCHAR(5), ROUTE_GROUP VARCHAR(20), CLASS VARCHAR(1), MENU_SPEC VARCHAR(12), DEP_STN VARCHAR(4), FLIGHTS NUMBER(5),
  MEALS_PLANNED NUMBER(9), MEALS_UPLIFTED NUMBER(9), MEALS_DOWNLIFTED NUMBER(9), MEALS_WASTED NUMBER(9), DOWNLIFT_LATE_CNT NUMBER(5), DELIVERIES_ON_TIME NUMBER(5),
  FOOD_COST NUMBER(14,2), LABOUR_COST NUMBER(14,2), OVERHEAD_COST NUMBER(14,2), BILL_AMOUNT NUMBER(14,2),
  src_system VARCHAR(20), extracted_at TIMESTAMP_NTZ, batch_id VARCHAR(50), row_hash VARCHAR(32)
) COMMENT = 'CMS historical backfill at daily x carrier x route group x class grain (Jan-2025 .. Aug-2026)';

CREATE OR REPLACE TABLE CMS_PRODUCTION_ORDERS (
  PROD_ORDER_ID VARCHAR(16), PROD_DATE DATE, KITCHEN VARCHAR(10), CLASS VARCHAR(1), MEALS_ORDERED NUMBER(9), MEALS_PRODUCED NUMBER(9), MEALS_WASTED NUMBER(9),
  SHIFT_PLAN VARCHAR(12), STATUS VARCHAR(10),
  src_system VARCHAR(20), extracted_at TIMESTAMP_NTZ, batch_id VARCHAR(50), row_hash VARCHAR(32)
);

CREATE OR REPLACE TABLE CMS_MENU_COST (
  MENU_SPEC VARCHAR(12), CARRIER VARCHAR(5), CLASS VARCHAR(1), VERSION NUMBER(2), VALID_FROM DATE, VALID_TO DATE, STD_FOOD_COST NUMBER(8,3),
  STD_LABOUR_COST NUMBER(8,3), STD_OVERHEAD_COST NUMBER(8,3), CHANGE_REASON VARCHAR(120),
  src_system VARCHAR(20), extracted_at TIMESTAMP_NTZ, batch_id VARCHAR(50), row_hash VARCHAR(32)
);

-- ------------------------------------------------------------------ Oracle airline-facing portals
CREATE OR REPLACE TABLE PORTAL_ORDERS_DAILY (
  ORDER_DATE DATE, AIRLINE VARCHAR(5), STATION VARCHAR(4), ORDERS_SUBMITTED NUMBER(6), ORDERS_AMENDED_AFTER_CUTOFF NUMBER(6), SPML_ORDERS NUMBER(7),
  SPML_UNFULFILLED NUMBER(6), SLA_EVENTS NUMBER(6), SLA_BREACHES NUMBER(6), AVG_LEAD_HOURS NUMBER(6,1),
  src_system VARCHAR(20), extracted_at TIMESTAMP_NTZ, batch_id VARCHAR(50), row_hash VARCHAR(32)
);

CREATE OR REPLACE TABLE PORTAL_SLA_EVENTS (
  EVENT_ID VARCHAR(12), EVENT_DATE DATE, AIRLINE VARCHAR(5), FLT_NO VARCHAR(10), SLA_TYPE VARCHAR(40), SLA_DEFINITION VARCHAR(120), TARGET_VALUE NUMBER(8,1),
  ACTUAL_VALUE NUMBER(8,1), BREACHED VARCHAR(1), ROOT_CAUSE VARCHAR(80),
  src_system VARCHAR(20), extracted_at TIMESTAMP_NTZ, batch_id VARCHAR(50), row_hash VARCHAR(32)
);

CREATE OR REPLACE TABLE PORTAL_SPECIAL_MEALS_MONTHLY (
  PERIOD VARCHAR(7), AIRLINE VARCHAR(5), SPML_CODE VARCHAR(4), ORDERS NUMBER(8), UNIT_PRICE_USD NUMBER(8,2),
  src_system VARCHAR(20), extracted_at TIMESTAMP_NTZ, batch_id VARCHAR(50), row_hash VARCHAR(32)
);

-- ------------------------------------------------------------------ SITA RMS (Type B messages)
CREATE OR REPLACE TABLE SITA_MESSAGES (
  MSG_ID VARCHAR(14), MSG_TYPE VARCHAR(3), FLT_NO VARCHAR(10), FLT_DATE DATE, AC_REG VARCHAR(8), ORIGIN VARCHAR(4), DEST VARCHAR(4), STATION VARCHAR(4),
  STD VARCHAR(16), ATD VARCHAR(16), DELAY_MIN NUMBER(5), DELAY_CODE VARCHAR(3), RAW_TEXT VARCHAR(200),
  src_system VARCHAR(20), extracted_at TIMESTAMP_NTZ, batch_id VARCHAR(50), row_hash VARCHAR(32)
) COMMENT = 'MVT and CAT messages, 16-30 Sep 2026 window (STD/ATD kept as text - parsed in Silver)';

-- ------------------------------------------------------------------ Reference masters and history archives (MDM hub, SAP, AODB, Maximo)
CREATE OR REPLACE TABLE MDM_ENTITIES (
  entity_key NUMBER(3), entity_code VARCHAR(10), entity_name VARCHAR(80), legal_name VARCHAR(120), country_code VARCHAR(2), local_currency VARCHAR(3),
  sap_company_code VARCHAR(4), sf_legal_entity_name VARCHAR(80), home_station VARCHAR(3),
  src_system VARCHAR(20), extracted_at TIMESTAMP_NTZ, batch_id VARCHAR(50), row_hash VARCHAR(32)
) COMMENT = 'MDM hub: legal entities';

CREATE OR REPLACE TABLE MDM_AIRLINES (
  airline_key NUMBER(4), airline_code VARCHAR(3), icao_code VARCHAR(3), airline_name VARCHAR(80), alliance VARCHAR(20), demo_alias VARCHAR(20), contract_type VARCHAR(40),
  contract_margin_pct NUMBER(5,3), base_load_factor NUMBER(5,3), catering_customer BOOLEAN, handling_customer BOOLEAN, country_code VARCHAR(2), account_manager VARCHAR(40),
  contract_id VARCHAR(20), contract_start DATE, contract_end DATE,
  src_system VARCHAR(20), extracted_at TIMESTAMP_NTZ, batch_id VARCHAR(50), row_hash VARCHAR(32)
) COMMENT = 'MDM hub: airline customers and their contracts';

CREATE OR REPLACE TABLE MDM_STATIONS (
  station_key NUMBER(3), station_code VARCHAR(3), icao_code VARCHAR(4), station_name VARCHAR(80), city VARCHAR(40), country_code VARCHAR(2), operating_entity_code VARCHAR(10), timezone VARCHAR(30),
  src_system VARCHAR(20), extracted_at TIMESTAMP_NTZ, batch_id VARCHAR(50), row_hash VARCHAR(32)
) COMMENT = 'MDM hub: stations';

CREATE OR REPLACE TABLE SAP_COST_CENTERS (
  cost_center_key NUMBER(4), cost_center_code VARCHAR(10), cost_center_name VARCHAR(80), entity_code VARCHAR(10), business_unit VARCHAR(40), station_code VARCHAR(3),
  target_headcount NUMBER(5), entity_key NUMBER(3), station_key NUMBER(3), cc_owner VARCHAR(40), is_operational BOOLEAN,
  src_system VARCHAR(20), extracted_at TIMESTAMP_NTZ, batch_id VARCHAR(50), row_hash VARCHAR(32)
) COMMENT = 'SAP CO cost centre master';

CREATE OR REPLACE TABLE SAP_GL_ACCOUNTS (
  gl_account_key NUMBER(4), gl_account VARCHAR(10), gl_description VARCHAR(80), account_class VARCHAR(20), kpi_group VARCHAR(30), is_ebitda BOOLEAN, is_intercompany BOOLEAN,
  natural_sign NUMBER(2), statement_line VARCHAR(30),
  src_system VARCHAR(20), extracted_at TIMESTAMP_NTZ, batch_id VARCHAR(50), row_hash VARCHAR(32)
) COMMENT = 'SAP FI chart of accounts with KPI mapping';

CREATE OR REPLACE TABLE AODB_FLIGHT_SCHEDULE (
  flight_key NUMBER(5), airline_code VARCHAR(3), flight_number VARCHAR(10), origin VARCHAR(3), destination VARCHAR(3), route_group VARCHAR(20), aircraft_type VARCHAR(6), days_of_week VARCHAR(7),
  station_code VARCHAR(3), service_entity_code VARCHAR(10), catered_by_asc BOOLEAN, handled_by_asc BOOLEAN, sched_dep_local VARCHAR(5), is_night_departure BOOLEAN,
  seats_f NUMBER(4), seats_j NUMBER(4), seats_y NUMBER(4), body_type VARCHAR(10), turnaround_fee_usd NUMBER(10,2), airline_key NUMBER(4), station_key NUMBER(3), entity_key NUMBER(3),
  src_system VARCHAR(20), extracted_at TIMESTAMP_NTZ, batch_id VARCHAR(50), row_hash VARCHAR(32)
) COMMENT = 'AODB seasonal flight schedule';

CREATE OR REPLACE TABLE MAXIMO_ASSET_HISTORY (
  asset_key NUMBER(6), asset_id VARCHAR(12), asset_type VARCHAR(40), asset_class VARCHAR(5), make VARCHAR(40), model VARCHAR(40), year_of_manufacture NUMBER(4),
  acquisition_cost_usd NUMBER(14,2), downtime_rate_usd_per_hr NUMBER(8,2), cost_center_code VARCHAR(10), station_code VARCHAR(3), entity_code VARCHAR(10), status VARCHAR(40), criticality VARCHAR(10),
  effective_from DATE, effective_to DATE, is_current BOOLEAN, version_no NUMBER(3), entity_key NUMBER(3), station_key NUMBER(3), cost_center_key NUMBER(4),
  src_system VARCHAR(20), extracted_at TIMESTAMP_NTZ, batch_id VARCHAR(50), row_hash VARCHAR(32)
) COMMENT = 'Maximo asset change log: one row per asset version (initial history for the SCD2 dimension)';

CREATE OR REPLACE TABLE AODB_DAILY_MOVEMENTS (
  date_key NUMBER(8), entity_key NUMBER(3), station_key NUMBER(3), airline_key NUMBER(4), route_group VARCHAR(20), flights_handled NUMBER(5), flights_catered NUMBER(5),
  departures_on_time NUMBER(5), total_delay_min NUMBER(8), handling_revenue_usd NUMBER(14,2),
  src_system VARCHAR(20), extracted_at TIMESTAMP_NTZ, batch_id VARCHAR(50), row_hash VARCHAR(32)
) COMMENT = 'AODB daily flight movements Jan-2025..Sep-2026; the live SITA window refreshes the last days';

-- ------------------------------------------------------------------ Contractor feeds (CSV from manpower agencies)
CREATE OR REPLACE TABLE CONTRACTOR_FEED_INVOICE_LINES (
  INVOICE_NO VARCHAR(30), INVOICE_DATE DATE, VENDOR_ID VARCHAR(10), CONTRACTOR_ID VARCHAR(10), CONTRACTOR_NAME VARCHAR(80), POOL_CC VARCHAR(10), DEPLOYED_CC VARCHAR(10),
  PERIOD VARCHAR(7), REG_HOURS NUMBER(7,2), OT_HOURS NUMBER(7,2), RATE_USD NUMBER(8,3), OT_RATE_USD NUMBER(8,3), AMOUNT_USD NUMBER(12,2), CURRENCY VARCHAR(3),
  src_system VARCHAR(20), extracted_at TIMESTAMP_NTZ, batch_id VARCHAR(50), row_hash VARCHAR(32)
) COMMENT = 'Monthly contractor invoice lines Jan-2025..Aug-2026 (strict format). Sep-2026 arrives as a daily drop file.';

-- Daily drop files have no audit columns: they are stamped at load time.
CREATE OR REPLACE TABLE CONTRACTOR_FEED_DAILY (
  INVOICE_NO VARCHAR(30), INVOICE_DATE DATE, VENDOR_ID VARCHAR(10), CONTRACTOR_ID VARCHAR(10), CONTRACTOR_NAME VARCHAR(80), POOL_CC VARCHAR(10), DEPLOYED_CC VARCHAR(10),
  PERIOD VARCHAR(7), REG_HOURS NUMBER(7,2), OT_HOURS NUMBER(7,2), RATE_USD NUMBER(8,3), OT_RATE_USD NUMBER(8,3), AMOUNT_USD NUMBER(12,2), CURRENCY VARCHAR(3),
  src_system VARCHAR(20) DEFAULT 'CONTRACTOR', extracted_at TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP(), batch_id VARCHAR(50), row_hash VARCHAR(32), file_name VARCHAR(400)
);

-- File contract for the daily drop: exactly the 14 columns a file must have. Used only to validate
-- files (COPY ... VALIDATION_MODE does not accept a column list, so it validates against this table).
CREATE OR REPLACE TABLE EDW_BRONZE.LANDING.CONTRACTOR_FEED_CONTRACT (
  INVOICE_NO VARCHAR(30), INVOICE_DATE DATE, VENDOR_ID VARCHAR(10), CONTRACTOR_ID VARCHAR(10), CONTRACTOR_NAME VARCHAR(80), POOL_CC VARCHAR(10), DEPLOYED_CC VARCHAR(10),
  PERIOD VARCHAR(7), REG_HOURS NUMBER(7,2), OT_HOURS NUMBER(7,2), RATE_USD NUMBER(8,3), OT_RATE_USD NUMBER(8,3), AMOUNT_USD NUMBER(12,2), CURRENCY VARCHAR(3)
) COMMENT = 'File contract for the daily contractor drop (14 columns). Validation only; never holds data.';

-- Lenient landing for suspect files: everything VARCHAR so DQ can inspect the rows
CREATE OR REPLACE TABLE EDW_BRONZE.QUARANTINE.CONTRACTOR_FEED_LENIENT (
  C1 VARCHAR, C2 VARCHAR, C3 VARCHAR, C4 VARCHAR, C5 VARCHAR, C6 VARCHAR, C7 VARCHAR, C8 VARCHAR, C9 VARCHAR, C10 VARCHAR,
  C11 VARCHAR, C12 VARCHAR, C13 VARCHAR, C14 VARCHAR, file_name VARCHAR(400), file_row_number NUMBER, landed_at TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP()
) COMMENT = 'Positional VARCHAR landing of files that failed the strict load';

-- =============================================================================
-- COPY INTO - strict loads (ABORT_STATEMENT so a bad file never half-loads)
-- =============================================================================
COPY INTO SAP_GL_ACTUALS_MONTHLY        FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/sap_gl_actuals_monthly.csv        FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'ABORT_STATEMENT';
COPY INTO SAP_CO_BUDGET_MONTHLY         FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/sap_co_budget_monthly.csv         FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'ABORT_STATEMENT';
COPY INTO SAP_PURCHASE_ORDERS           FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/sap_purchase_orders.csv           FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'ABORT_STATEMENT';
COPY INTO SAP_VENDOR_MASTER             FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/sap_vendor_master.csv             FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'ABORT_STATEMENT';
COPY INTO SF_EMPLOYEE_MASTER            FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/sf_employee_master.csv            FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'ABORT_STATEMENT';
COPY INTO SF_TIME_ENTRIES_MONTHLY       FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/sf_time_entries_monthly.csv       FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'ABORT_STATEMENT';
COPY INTO ARIBA_SUPPLIERS               FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/ariba_suppliers.csv               FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'ABORT_STATEMENT';
COPY INTO ARIBA_REQUISITIONS            FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/ariba_requisitions.csv            FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'ABORT_STATEMENT';
COPY INTO MAXIMO_ASSETS                 FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/maximo_assets.csv                 FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'ABORT_STATEMENT';
COPY INTO MAXIMO_WORK_ORDERS            FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/maximo_work_orders.csv            FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'ABORT_STATEMENT';
COPY INTO MAXIMO_METER_READINGS         FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/maximo_meter_readings.csv         FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'ABORT_STATEMENT';
COPY INTO CMS_UPLIFT_FLIGHT_CLASS       FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/cms_uplift_flight_class.csv       FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'ABORT_STATEMENT';
COPY INTO CMS_UPLIFT_DAILY_HISTORY      FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/cms_uplift_daily_history.csv      FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'ABORT_STATEMENT';
COPY INTO CMS_PRODUCTION_ORDERS         FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/cms_production_orders.csv         FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'ABORT_STATEMENT';
COPY INTO CMS_MENU_COST                 FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/cms_menu_cost.csv                 FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'ABORT_STATEMENT';
COPY INTO PORTAL_ORDERS_DAILY           FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/portal_orders_daily.csv           FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'ABORT_STATEMENT';
COPY INTO PORTAL_SLA_EVENTS             FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/portal_sla_events.csv             FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'ABORT_STATEMENT';
COPY INTO PORTAL_SPECIAL_MEALS_MONTHLY  FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/portal_special_meals_monthly.csv  FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'ABORT_STATEMENT';
COPY INTO SITA_MESSAGES                 FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/sita_messages.csv                 FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'ABORT_STATEMENT';
COPY INTO CONTRACTOR_FEED_INVOICE_LINES FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/contractor_feed_invoice_lines.csv FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'ABORT_STATEMENT';
COPY INTO MDM_ENTITIES                  FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/mdm_entities.csv FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'ABORT_STATEMENT';
COPY INTO MDM_AIRLINES                  FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/mdm_airlines.csv FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'ABORT_STATEMENT';
COPY INTO MDM_STATIONS                  FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/mdm_stations.csv FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'ABORT_STATEMENT';
COPY INTO SAP_COST_CENTERS              FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/sap_cost_centers.csv FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'ABORT_STATEMENT';
COPY INTO SAP_GL_ACCOUNTS               FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/sap_gl_accounts.csv FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'ABORT_STATEMENT';
COPY INTO AODB_FLIGHT_SCHEDULE          FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/aodb_flight_schedule.csv FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'ABORT_STATEMENT';
COPY INTO MAXIMO_ASSET_HISTORY          FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bronze/maximo_asset_history.csv FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'ABORT_STATEMENT';
