-- Record the strict loads in the file log (COPY_HISTORY is the system of record; this is the demo-visible copy)
INSERT INTO EDW_BRONZE.LANDING.FILE_LOAD_LOG (src_system, file_name, target_table, status, rows_parsed, rows_loaded, error_count, batch_id)
SELECT SPLIT_PART(table_name, '_', 1), file_name, table_name, IFF(error_count = 0, 'LOADED', 'REJECTED'), row_parsed, row_count, error_count, 'BRONZE_FULL_LOAD'
FROM (
  SELECT * FROM TABLE(EDW_BRONZE.INFORMATION_SCHEMA.COPY_HISTORY(TABLE_NAME => 'EDW_BRONZE.RAW.SAP_GL_ACTUALS_MONTHLY', START_TIME => DATEADD(hour, -1, CURRENT_TIMESTAMP())))
  UNION ALL SELECT * FROM TABLE(EDW_BRONZE.INFORMATION_SCHEMA.COPY_HISTORY(TABLE_NAME => 'EDW_BRONZE.RAW.SAP_CO_BUDGET_MONTHLY', START_TIME => DATEADD(hour, -1, CURRENT_TIMESTAMP())))
  UNION ALL SELECT * FROM TABLE(EDW_BRONZE.INFORMATION_SCHEMA.COPY_HISTORY(TABLE_NAME => 'EDW_BRONZE.RAW.SAP_PURCHASE_ORDERS', START_TIME => DATEADD(hour, -1, CURRENT_TIMESTAMP())))
  UNION ALL SELECT * FROM TABLE(EDW_BRONZE.INFORMATION_SCHEMA.COPY_HISTORY(TABLE_NAME => 'EDW_BRONZE.RAW.SAP_VENDOR_MASTER', START_TIME => DATEADD(hour, -1, CURRENT_TIMESTAMP())))
  UNION ALL SELECT * FROM TABLE(EDW_BRONZE.INFORMATION_SCHEMA.COPY_HISTORY(TABLE_NAME => 'EDW_BRONZE.RAW.SF_EMPLOYEE_MASTER', START_TIME => DATEADD(hour, -1, CURRENT_TIMESTAMP())))
  UNION ALL SELECT * FROM TABLE(EDW_BRONZE.INFORMATION_SCHEMA.COPY_HISTORY(TABLE_NAME => 'EDW_BRONZE.RAW.SF_TIME_ENTRIES_MONTHLY', START_TIME => DATEADD(hour, -1, CURRENT_TIMESTAMP())))
  UNION ALL SELECT * FROM TABLE(EDW_BRONZE.INFORMATION_SCHEMA.COPY_HISTORY(TABLE_NAME => 'EDW_BRONZE.RAW.ARIBA_SUPPLIERS', START_TIME => DATEADD(hour, -1, CURRENT_TIMESTAMP())))
  UNION ALL SELECT * FROM TABLE(EDW_BRONZE.INFORMATION_SCHEMA.COPY_HISTORY(TABLE_NAME => 'EDW_BRONZE.RAW.ARIBA_REQUISITIONS', START_TIME => DATEADD(hour, -1, CURRENT_TIMESTAMP())))
  UNION ALL SELECT * FROM TABLE(EDW_BRONZE.INFORMATION_SCHEMA.COPY_HISTORY(TABLE_NAME => 'EDW_BRONZE.RAW.MAXIMO_ASSETS', START_TIME => DATEADD(hour, -1, CURRENT_TIMESTAMP())))
  UNION ALL SELECT * FROM TABLE(EDW_BRONZE.INFORMATION_SCHEMA.COPY_HISTORY(TABLE_NAME => 'EDW_BRONZE.RAW.MAXIMO_WORK_ORDERS', START_TIME => DATEADD(hour, -1, CURRENT_TIMESTAMP())))
  UNION ALL SELECT * FROM TABLE(EDW_BRONZE.INFORMATION_SCHEMA.COPY_HISTORY(TABLE_NAME => 'EDW_BRONZE.RAW.MAXIMO_METER_READINGS', START_TIME => DATEADD(hour, -1, CURRENT_TIMESTAMP())))
  UNION ALL SELECT * FROM TABLE(EDW_BRONZE.INFORMATION_SCHEMA.COPY_HISTORY(TABLE_NAME => 'EDW_BRONZE.RAW.CMS_UPLIFT_FLIGHT_CLASS', START_TIME => DATEADD(hour, -1, CURRENT_TIMESTAMP())))
  UNION ALL SELECT * FROM TABLE(EDW_BRONZE.INFORMATION_SCHEMA.COPY_HISTORY(TABLE_NAME => 'EDW_BRONZE.RAW.CMS_UPLIFT_DAILY_HISTORY', START_TIME => DATEADD(hour, -1, CURRENT_TIMESTAMP())))
  UNION ALL SELECT * FROM TABLE(EDW_BRONZE.INFORMATION_SCHEMA.COPY_HISTORY(TABLE_NAME => 'EDW_BRONZE.RAW.CMS_PRODUCTION_ORDERS', START_TIME => DATEADD(hour, -1, CURRENT_TIMESTAMP())))
  UNION ALL SELECT * FROM TABLE(EDW_BRONZE.INFORMATION_SCHEMA.COPY_HISTORY(TABLE_NAME => 'EDW_BRONZE.RAW.CMS_MENU_COST', START_TIME => DATEADD(hour, -1, CURRENT_TIMESTAMP())))
  UNION ALL SELECT * FROM TABLE(EDW_BRONZE.INFORMATION_SCHEMA.COPY_HISTORY(TABLE_NAME => 'EDW_BRONZE.RAW.PORTAL_ORDERS_DAILY', START_TIME => DATEADD(hour, -1, CURRENT_TIMESTAMP())))
  UNION ALL SELECT * FROM TABLE(EDW_BRONZE.INFORMATION_SCHEMA.COPY_HISTORY(TABLE_NAME => 'EDW_BRONZE.RAW.PORTAL_SLA_EVENTS', START_TIME => DATEADD(hour, -1, CURRENT_TIMESTAMP())))
  UNION ALL SELECT * FROM TABLE(EDW_BRONZE.INFORMATION_SCHEMA.COPY_HISTORY(TABLE_NAME => 'EDW_BRONZE.RAW.PORTAL_SPECIAL_MEALS_MONTHLY', START_TIME => DATEADD(hour, -1, CURRENT_TIMESTAMP())))
  UNION ALL SELECT * FROM TABLE(EDW_BRONZE.INFORMATION_SCHEMA.COPY_HISTORY(TABLE_NAME => 'EDW_BRONZE.RAW.SITA_MESSAGES', START_TIME => DATEADD(hour, -1, CURRENT_TIMESTAMP())))
  UNION ALL SELECT * FROM TABLE(EDW_BRONZE.INFORMATION_SCHEMA.COPY_HISTORY(TABLE_NAME => 'EDW_BRONZE.RAW.CONTRACTOR_FEED_INVOICE_LINES', START_TIME => DATEADD(hour, -1, CURRENT_TIMESTAMP())))
  UNION ALL SELECT * FROM TABLE(EDW_BRONZE.INFORMATION_SCHEMA.COPY_HISTORY(TABLE_NAME => 'EDW_BRONZE.RAW.MDM_ENTITIES', START_TIME => DATEADD(hour, -1, CURRENT_TIMESTAMP())))
  UNION ALL SELECT * FROM TABLE(EDW_BRONZE.INFORMATION_SCHEMA.COPY_HISTORY(TABLE_NAME => 'EDW_BRONZE.RAW.MDM_AIRLINES', START_TIME => DATEADD(hour, -1, CURRENT_TIMESTAMP())))
  UNION ALL SELECT * FROM TABLE(EDW_BRONZE.INFORMATION_SCHEMA.COPY_HISTORY(TABLE_NAME => 'EDW_BRONZE.RAW.MDM_STATIONS', START_TIME => DATEADD(hour, -1, CURRENT_TIMESTAMP())))
  UNION ALL SELECT * FROM TABLE(EDW_BRONZE.INFORMATION_SCHEMA.COPY_HISTORY(TABLE_NAME => 'EDW_BRONZE.RAW.SAP_COST_CENTERS', START_TIME => DATEADD(hour, -1, CURRENT_TIMESTAMP())))
  UNION ALL SELECT * FROM TABLE(EDW_BRONZE.INFORMATION_SCHEMA.COPY_HISTORY(TABLE_NAME => 'EDW_BRONZE.RAW.SAP_GL_ACCOUNTS', START_TIME => DATEADD(hour, -1, CURRENT_TIMESTAMP())))
  UNION ALL SELECT * FROM TABLE(EDW_BRONZE.INFORMATION_SCHEMA.COPY_HISTORY(TABLE_NAME => 'EDW_BRONZE.RAW.AODB_FLIGHT_SCHEDULE', START_TIME => DATEADD(hour, -1, CURRENT_TIMESTAMP())))
  UNION ALL SELECT * FROM TABLE(EDW_BRONZE.INFORMATION_SCHEMA.COPY_HISTORY(TABLE_NAME => 'EDW_BRONZE.RAW.MAXIMO_ASSET_HISTORY', START_TIME => DATEADD(hour, -1, CURRENT_TIMESTAMP())))
  UNION ALL SELECT * FROM TABLE(EDW_BRONZE.INFORMATION_SCHEMA.COPY_HISTORY(TABLE_NAME => 'EDW_BRONZE.RAW.AODB_DAILY_MOVEMENTS', START_TIME => DATEADD(hour, -1, CURRENT_TIMESTAMP())))
);

-- =============================================================================
-- Daily contractor drop: STEP A - validate the file WITHOUT loading
-- (Demo: run on the malformed file first, then on the clean file.)
-- =============================================================================
-- A1. Structural validation of the malformed file -> returns the parse errors instead of loading
COPY INTO EDW_BRONZE.LANDING.CONTRACTOR_FEED_CONTRACT
FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bad_files/contractor_feed_2026-09-28_malformed.csv
FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD')
VALIDATION_MODE = 'RETURN_ERRORS';
-- Expected: "Number of columns in file (12) does not match that of the corresponding table (14)" plus
--           date / numeric conversion errors. Nothing is written to CONTRACTOR_FEED_DAILY.

-- A2. Log the rejection and move the file to the quarantine stage
INSERT INTO EDW_BRONZE.LANDING.FILE_LOAD_LOG (src_system, file_name, target_table, status, rows_parsed, rows_loaded, error_count, first_error, batch_id)
VALUES ('CONTRACTOR', 'bad_files/contractor_feed_2026-09-28_malformed.csv', 'EDW_BRONZE.RAW.CONTRACTOR_FEED_DAILY', 'QUARANTINED', 373, 0, 373,
        'Column count mismatch: file has 12 columns, contract expects 14 (missing DEPLOYED_CC, OT_RATE_USD)', 'CONTRACTOR_20260928_001');
COPY FILES INTO @EDW_BRONZE.LANDING.STG_QUARANTINE/2026-09-28/
  FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bad_files/
  FILES = ('contractor_feed_2026-09-28_malformed.csv');

-- A3. Land the malformed file leniently (positional VARCHAR) so Silver DQ can show WHICH rows are wrong
COPY INTO EDW_BRONZE.QUARANTINE.CONTRACTOR_FEED_LENIENT (C1, C2, C3, C4, C5, C6, C7, C8, C9, C10, C11, C12, C13, C14, file_name, file_row_number)
FROM (SELECT t.$1, t.$2, t.$3, t.$4, t.$5, t.$6, t.$7, t.$8, t.$9, t.$10, t.$11, t.$12, t.$13, t.$14, METADATA$FILENAME, METADATA$FILE_ROW_NUMBER
      FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bad_files/contractor_feed_2026-09-28_malformed.csv t)
FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_LENIENT') ON_ERROR = 'CONTINUE';

-- =============================================================================
-- Daily contractor drop: STEP B - the corrected file passes and is stamped with audit columns
-- =============================================================================
COPY INTO CONTRACTOR_FEED_DAILY (INVOICE_NO, INVOICE_DATE, VENDOR_ID, CONTRACTOR_ID, CONTRACTOR_NAME, POOL_CC, DEPLOYED_CC, PERIOD, REG_HOURS, OT_HOURS, RATE_USD, OT_RATE_USD, AMOUNT_USD, CURRENCY, batch_id, row_hash, file_name)
FROM (SELECT t.$1, t.$2, t.$3, t.$4, t.$5, t.$6, t.$7, t.$8, t.$9, t.$10, t.$11, t.$12, t.$13, t.$14,
             'CONTRACTOR_20260928_002',
             LEFT(MD5(CONCAT_WS('|', t.$1, t.$2, t.$3, t.$4, t.$5, t.$6, t.$7, t.$8, t.$9, t.$10, t.$11, t.$12, t.$13, t.$14)), 12),
             METADATA$FILENAME
      FROM @EDW_BRONZE.LANDING.STG_SOURCE_DROP/bad_files/contractor_feed_2026-09-28_clean.csv t)
FILE_FORMAT = (FORMAT_NAME = 'EDW_BRONZE.LANDING.FF_CSV_STD') ON_ERROR = 'ABORT_STATEMENT';

INSERT INTO EDW_BRONZE.LANDING.FILE_LOAD_LOG (src_system, file_name, target_table, status, rows_parsed, rows_loaded, error_count, batch_id)
SELECT 'CONTRACTOR', 'bad_files/contractor_feed_2026-09-28_clean.csv', 'EDW_BRONZE.RAW.CONTRACTOR_FEED_DAILY', 'LOADED', COUNT(*), COUNT(*), 0, 'CONTRACTOR_20260928_002'
FROM CONTRACTOR_FEED_DAILY WHERE batch_id = 'CONTRACTOR_20260928_002';

-- =============================================================================
-- Quick Bronze inventory (shown on screen after ingest)
-- =============================================================================
SELECT 'SAP_GL_ACTUALS_MONTHLY' AS object, COUNT(*) AS rows_landed, MIN(extracted_at) AS first_extract, MAX(extracted_at) AS last_extract, COUNT(DISTINCT batch_id) AS batches FROM SAP_GL_ACTUALS_MONTHLY
UNION ALL SELECT 'SAP_CO_BUDGET_MONTHLY', COUNT(*), MIN(extracted_at), MAX(extracted_at), COUNT(DISTINCT batch_id) FROM SAP_CO_BUDGET_MONTHLY
UNION ALL SELECT 'SAP_PURCHASE_ORDERS', COUNT(*), MIN(extracted_at), MAX(extracted_at), COUNT(DISTINCT batch_id) FROM SAP_PURCHASE_ORDERS
UNION ALL SELECT 'SAP_VENDOR_MASTER', COUNT(*), MIN(extracted_at), MAX(extracted_at), COUNT(DISTINCT batch_id) FROM SAP_VENDOR_MASTER
UNION ALL SELECT 'SF_EMPLOYEE_MASTER', COUNT(*), MIN(extracted_at), MAX(extracted_at), COUNT(DISTINCT batch_id) FROM SF_EMPLOYEE_MASTER
UNION ALL SELECT 'SF_TIME_ENTRIES_MONTHLY', COUNT(*), MIN(extracted_at), MAX(extracted_at), COUNT(DISTINCT batch_id) FROM SF_TIME_ENTRIES_MONTHLY
UNION ALL SELECT 'ARIBA_SUPPLIERS', COUNT(*), MIN(extracted_at), MAX(extracted_at), COUNT(DISTINCT batch_id) FROM ARIBA_SUPPLIERS
UNION ALL SELECT 'ARIBA_REQUISITIONS', COUNT(*), MIN(extracted_at), MAX(extracted_at), COUNT(DISTINCT batch_id) FROM ARIBA_REQUISITIONS
UNION ALL SELECT 'MAXIMO_ASSETS', COUNT(*), MIN(extracted_at), MAX(extracted_at), COUNT(DISTINCT batch_id) FROM MAXIMO_ASSETS
UNION ALL SELECT 'MAXIMO_WORK_ORDERS', COUNT(*), MIN(extracted_at), MAX(extracted_at), COUNT(DISTINCT batch_id) FROM MAXIMO_WORK_ORDERS
UNION ALL SELECT 'MAXIMO_METER_READINGS', COUNT(*), MIN(extracted_at), MAX(extracted_at), COUNT(DISTINCT batch_id) FROM MAXIMO_METER_READINGS
UNION ALL SELECT 'CMS_UPLIFT_FLIGHT_CLASS', COUNT(*), MIN(extracted_at), MAX(extracted_at), COUNT(DISTINCT batch_id) FROM CMS_UPLIFT_FLIGHT_CLASS
UNION ALL SELECT 'CMS_UPLIFT_DAILY_HISTORY', COUNT(*), MIN(extracted_at), MAX(extracted_at), COUNT(DISTINCT batch_id) FROM CMS_UPLIFT_DAILY_HISTORY
UNION ALL SELECT 'CMS_PRODUCTION_ORDERS', COUNT(*), MIN(extracted_at), MAX(extracted_at), COUNT(DISTINCT batch_id) FROM CMS_PRODUCTION_ORDERS
UNION ALL SELECT 'CMS_MENU_COST', COUNT(*), MIN(extracted_at), MAX(extracted_at), COUNT(DISTINCT batch_id) FROM CMS_MENU_COST
UNION ALL SELECT 'PORTAL_ORDERS_DAILY', COUNT(*), MIN(extracted_at), MAX(extracted_at), COUNT(DISTINCT batch_id) FROM PORTAL_ORDERS_DAILY
UNION ALL SELECT 'PORTAL_SLA_EVENTS', COUNT(*), MIN(extracted_at), MAX(extracted_at), COUNT(DISTINCT batch_id) FROM PORTAL_SLA_EVENTS
UNION ALL SELECT 'PORTAL_SPECIAL_MEALS_MONTHLY', COUNT(*), MIN(extracted_at), MAX(extracted_at), COUNT(DISTINCT batch_id) FROM PORTAL_SPECIAL_MEALS_MONTHLY
UNION ALL SELECT 'SITA_MESSAGES', COUNT(*), MIN(extracted_at), MAX(extracted_at), COUNT(DISTINCT batch_id) FROM SITA_MESSAGES
UNION ALL SELECT 'CONTRACTOR_FEED_INVOICE_LINES', COUNT(*), MIN(extracted_at), MAX(extracted_at), COUNT(DISTINCT batch_id) FROM CONTRACTOR_FEED_INVOICE_LINES
UNION ALL SELECT 'CONTRACTOR_FEED_DAILY', COUNT(*), MIN(extracted_at), MAX(extracted_at), COUNT(DISTINCT batch_id) FROM CONTRACTOR_FEED_DAILY
UNION ALL SELECT 'MDM_ENTITIES', COUNT(*), MIN(extracted_at), MAX(extracted_at), COUNT(DISTINCT batch_id) FROM MDM_ENTITIES
UNION ALL SELECT 'MDM_AIRLINES', COUNT(*), MIN(extracted_at), MAX(extracted_at), COUNT(DISTINCT batch_id) FROM MDM_AIRLINES
UNION ALL SELECT 'MDM_STATIONS', COUNT(*), MIN(extracted_at), MAX(extracted_at), COUNT(DISTINCT batch_id) FROM MDM_STATIONS
UNION ALL SELECT 'SAP_COST_CENTERS', COUNT(*), MIN(extracted_at), MAX(extracted_at), COUNT(DISTINCT batch_id) FROM SAP_COST_CENTERS
UNION ALL SELECT 'SAP_GL_ACCOUNTS', COUNT(*), MIN(extracted_at), MAX(extracted_at), COUNT(DISTINCT batch_id) FROM SAP_GL_ACCOUNTS
UNION ALL SELECT 'AODB_FLIGHT_SCHEDULE', COUNT(*), MIN(extracted_at), MAX(extracted_at), COUNT(DISTINCT batch_id) FROM AODB_FLIGHT_SCHEDULE
UNION ALL SELECT 'MAXIMO_ASSET_HISTORY', COUNT(*), MIN(extracted_at), MAX(extracted_at), COUNT(DISTINCT batch_id) FROM MAXIMO_ASSET_HISTORY
UNION ALL SELECT 'AODB_DAILY_MOVEMENTS', COUNT(*), MIN(extracted_at), MAX(extracted_at), COUNT(DISTINCT batch_id) FROM AODB_DAILY_MOVEMENTS
ORDER BY 1;
